// shouldPromptBootstrapSetupChoice reports whether this is the bare
// interactive bootstrap path. Any option that expresses a granular choice
// keeps the established flag behavior instead of being overwritten by a
// preset.
func shouldPromptBootstrapSetupChoice(opts GitHubBootstrapOptions) bool {
	return interactive.CanPromptInteractively() &&
		!opts.Yes &&
		!opts.NoGitHub &&
		!ghFlagsProvided(opts) &&
		!opts.Push &&
		opts.InitialCommitMessage == "" &&
		!opts.SkipInitialCommit
}

// promptBootstrapSetupChoice collapses the common bootstrap decisions into a
// single preset selection. The repository has already been initialized at
// this point; the selected commit is still deferred until Entire has written
// its settings and agent configuration.
func promptBootstrapSetupChoice(w io.Writer, githubReady bool) (bootstrapSetupChoice, error) {
	options := []huh.Option[bootstrapSetupChoice]{
		huh.NewOption("Create one initial commit locally (recommended)", bootstrapSetupLocal),
	}
	if githubReady {
		options = append(options,
			huh.NewOption("Create a private GitHub repository and push one initial commit", bootstrapSetupGitHub),
		)
	}
	options = append(options,
		huh.NewOption("Customize Git setup...", bootstrapSetupCustom),
	)

	choice := bootstrapSetupLocal
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[bootstrapSetupChoice]().
				Title("When Entire configuration is ready").
				Options(options...).
				Value(&choice),
		),
	).WithOutput(w)
	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) {
			return "", errBootstrapInterrupted
		}
		return "", fmt.Errorf("git setup prompt: %w", err)
	}
	return choice, nil
}

